CREATE TABLE IF NOT EXISTS `work_task` (`created_at` BIGINT NOT NULL, `due_at` BIGINT NULL, `id` BIGINT NOT NULL AUTO_INCREMENT, `owner_user` BIGINT NOT NULL, `parent_task` BIGINT NULL, `priority` ENUM('low', 'normal', 'high') NOT NULL DEFAULT 'normal', `project_project` BIGINT NOT NULL, `status` ENUM('todo', 'doing', 'done') NOT NULL DEFAULT 'todo', `title` VARCHAR(160) NOT NULL, `updated_at` BIGINT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_work_task_id_project_owner` (`id`, `project_project`, `owner_user`), KEY `idx_work_task_owner_project_status` (`owner_user`, `project_project`, `status`), KEY `idx_work_task_owner_parent` (`owner_user`, `parent_task`), CONSTRAINT `fk_work_task_owner` FOREIGN KEY (`owner_user`) REFERENCES `users` (`id`) ON UPDATE RESTRICT ON DELETE RESTRICT, CONSTRAINT `fk_work_task_project_owner` FOREIGN KEY (`project_project`, `owner_user`) REFERENCES `work_project` (`id`, `owner_user`) ON UPDATE RESTRICT ON DELETE RESTRICT, CONSTRAINT `fk_work_task_parent_project_owner` FOREIGN KEY (`parent_task`, `project_project`, `owner_user`) REFERENCES `work_task` (`id`, `project_project`, `owner_user`) ON UPDATE RESTRICT ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
